import React, { useEffect, useRef, useState } from 'react';

/**
 * 60-Minute Future Forecast Component
 * Visualizes authentic predictions generated by the trained LSTM model (lstm_model.keras)
 * Color: Purple (#8b5cf6)
 * Supports live LSTM model inference triggering across customizable forecast horizons.
 */
export const FutureForecastChart = ({
  data = [],
  loading = false,
  error = null,
  isLiveApi = false,
  onRetry,
  onGenerateLiveForecast
}) => {
  const canvasRef = useRef(null);
  const chartInstanceRef = useRef(null);
  const [selectedHorizon, setSelectedHorizon] = useState(60);
  const [generating, setGenerating] = useState(false);

  const formatUtcTime = (isoStr) => {
    const d = new Date(isoStr);
    const hours = String(d.getUTCHours()).padStart(2, '0');
    const mins = String(d.getUTCMinutes()).padStart(2, '0');
    return `${hours}:${mins} UTC`;
  };

  const formatUtcFull = (isoStr) => {
    const d = new Date(isoStr);
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    return `${months[d.getUTCMonth()]} ${d.getUTCDate()}, ${String(d.getUTCHours()).padStart(2, '0')}:${String(d.getUTCMinutes()).padStart(2, '0')} UTC`;
  };

  const handleGenerateClick = async () => {
    if (!onGenerateLiveForecast || generating) return;
    setGenerating(true);
    try {
      await onGenerateLiveForecast(selectedHorizon);
    } catch (err) {
      console.error('Failed to generate forecast:', err);
    } finally {
      setGenerating(false);
    }
  };

  useEffect(() => {
    if (!canvasRef.current || !data || data.length === 0) {
      if (chartInstanceRef.current) {
        chartInstanceRef.current.destroy();
        chartInstanceRef.current = null;
      }
      return;
    }

    const Chart = window.Chart;
    if (!Chart) return;

    const ctx = canvasRef.current.getContext('2d');
    if (chartInstanceRef.current) {
      chartInstanceRef.current.destroy();
    }

    const labels = data.map(d => formatUtcTime(d.timestamp));
    const values = data.map(d => d.forecast_power_w);

    const grad = ctx.createLinearGradient(0, 0, 0, 380);
    grad.addColorStop(0, 'rgba(124, 58, 237, 0.12)');
    grad.addColorStop(1, 'rgba(124, 58, 237, 0.01)');

    chartInstanceRef.current = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [
          {
            label: `${data.length}-Minute Future Forecast (W)`,
            data: values,
            borderColor: '#7c3aed',
            backgroundColor: grad,
            borderWidth: 2,
            pointRadius: 2.5,
            pointHoverRadius: 6,
            pointBackgroundColor: '#7c3aed',
            pointHoverBackgroundColor: '#6d28d9',
            pointBorderColor: '#ffffff',
            pointBorderWidth: 1.5,
            tension: 0,
            fill: true
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        interaction: { mode: 'index', intersect: false },
        plugins: {
          legend: {
            display: true,
            position: 'top',
            align: 'end',
            labels: {
              boxWidth: 9,
              padding: 14,
              color: '#334155',
              font: { weight: '600', family: "'Inter', sans-serif", size: 12 }
            }
          },
          tooltip: {
            backgroundColor: '#0f172a',
            titleColor: '#ffffff',
            bodyColor: '#cbd5e1',
            borderColor: '#334155',
            borderWidth: 1,
            padding: 10,
            cornerRadius: 8,
            callbacks: {
              title: (items) => {
                const idx = items[0].dataIndex;
                const d = data[idx];
                return `Forecast Horizon: Minute ${d.step} of ${data.length} (${formatUtcFull(d.timestamp)})`;
              },
              label: (item) => ` Model Forecast Power: ${Number(item.raw).toFixed(2)} W`,
              afterBody: () => ' [Trained LSTM Model Forecast — Watts (W)]'
            }
          }
        },
        scales: {
          x: {
            grid: { color: '#f1f5f9' },
            ticks: {
              maxRotation: 0,
              autoSkip: true,
              maxTicksLimit: 12,
              color: '#64748b',
              font: { family: "'JetBrains Mono', monospace", size: 11 }
            }
          },
          y: {
            grid: { color: '#f1f5f9' },
            title: {
              display: true,
              text: 'Active Power Demand (Watts)',
              color: '#475569',
              font: { weight: '600', size: 11 }
            },
            ticks: {
              color: '#64748b',
              font: { family: "'JetBrains Mono', monospace", size: 11 },
              callback: (val) => `${val} W`
            }
          }
        }
      }
    });

    return () => {
      if (chartInstanceRef.current) {
        chartInstanceRef.current.destroy();
        chartInstanceRef.current = null;
      }
    };
  }, [data]);

  return (
    <section className="dashboard-section" id="forecast-section" aria-label="Future Demand Forecast">
      <div className="section-header">
        <div className="section-title-wrap">
          <span className="section-num-badge">3</span>
          <div>
            <h2 className="section-title">Future Electricity Demand Forecast</h2>
            <p className="section-subtitle">
              Autoregressive forward projection of power demand in Watts (W) generated by trained LSTM model
            </p>
          </div>
        </div>

        <div className="card-actions" style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', flexWrap: 'wrap' }}>
          <div className="chart-meta-tags">
            <span className="badge-indicator badge-forecast">
              <span className="color-dot dot-forecast"></span>
              Future Forecast
            </span>
            <span className="badge-indicator badge-neutral">
              Horizon: {data?.length || 60} Minutes
            </span>
          </div>

          {onGenerateLiveForecast && (
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              <select
                value={selectedHorizon}
                onChange={(e) => setSelectedHorizon(Number(e.target.value))}
                style={{
                  background: '#ffffff',
                  color: '#0f172a',
                  border: '1px solid #cbd5e1',
                  borderRadius: 'var(--radius-sm, 6px)',
                  padding: '0.35rem 0.6rem',
                  fontSize: '0.8rem',
                  cursor: 'pointer'
                }}
                disabled={generating || loading}
                aria-label="Select Forecast Horizon in Minutes"
              >
                <option value={15}>15 Minutes</option>
                <option value={30}>30 Minutes</option>
                <option value={60}>60 Minutes</option>
                <option value={90}>90 Minutes</option>
                <option value={120}>120 Minutes</option>
              </select>

              <button
                className="btn btn-primary btn-sm"
                onClick={handleGenerateClick}
                disabled={generating || loading}
                style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', whiteSpace: 'nowrap' }}
              >
                {generating ? (
                  <>
                    <span className="loading-mini-spinner" style={{ width: '12px', height: '12px', borderWidth: '1.5px', borderTopColor: '#ffffff' }} />
                    Generating...
                  </>
                ) : (
                  <>
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                      <polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"></polygon>
                    </svg>
                    Run Forecast
                  </>
                )}
              </button>
            </div>
          )}
        </div>
      </div>

      <article className="glass-card">
        {/* Informational Note */}
        <div className="forecast-notice-banner" role="note">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
            <circle cx="12" cy="12" r="10"></circle>
            <line x1="12" y1="16" x2="12" y2="12"></line>
            <line x1="12" y1="8" x2="12.01" y2="8"></line>
          </svg>
          <div>
            <strong>Operational Note:</strong> Recursive multi-step forward inference beyond the historical telemetry boundary.{' '}
            <span style={{ color: 'var(--text-secondary)', marginLeft: '0.25rem' }}>
              These values are calculated in physical <strong>Watts (W)</strong> by feeding the trained LSTM output back into the 30-minute sliding window.
            </span>
          </div>
        </div>

        {/* Dynamic Forecast Canvas */}
        <div className="chart-container-large" id="futureForecastContainer" style={{ position: 'relative' }}>
          {(loading || generating) && (
            <div className="chart-loading-overlay">
              <div className="loading-mini-spinner" aria-hidden="true"></div>
              <span>Generating recursive future forecast with trained LSTM model...</span>
            </div>
          )}

          {(!loading && !generating && (error || !data || data.length === 0)) && (
            <div className="chart-empty-state">
              <div className="empty-icon-wrap" aria-hidden="true">
                <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                  <circle cx="12" cy="12" r="10"></circle>
                  <line x1="12" y1="8" x2="12" y2="12"></line>
                  <line x1="12" y1="16" x2="12.01" y2="16"></line>
                </svg>
              </div>
              <h4 className="empty-state-title">Future Forecast Unavailable</h4>
              <p className="empty-state-desc">
                {error || 'Unable to load forecast from backend API. Please verify that server.py is running.'}
              </p>
              {onRetry && (
                <button className="btn btn-secondary btn-sm" onClick={onRetry}>
                  Retry Loading Data
                </button>
              )}
            </div>
          )}

          <canvas ref={canvasRef} id="futureForecastChart" />
        </div>

        {/* Step Horizon Grid */}
        <div className="forecast-steps-grid" id="forecastStepsGrid" aria-label="Minute-by-minute forecast horizon points">
          {(!data || data.length === 0) ? (
            <div style={{ gridColumn: '1 / -1', padding: '1.75rem', textAlign: 'center', color: 'var(--text-muted)', fontSize: '0.84rem', border: '1px dashed var(--border-subtle)', borderRadius: 'var(--radius-md)' }}>
              Recursive forecast steps unavailable because forecast data could not be loaded.
            </div>
          ) : (
            data.map(d => {
              const dt = new Date(d.timestamp);
              const timeStr = dt.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false });
              return (
                <div className="forecast-step-card" key={d.step}>
                  <div className="step-num">+{d.step} MIN (t+{d.horizon_minute})</div>
                  <div className="step-val">{Number(d.forecast_power_w).toFixed(2)} W</div>
                  <div className="step-time">{timeStr} UTC</div>
                </div>
              );
            })
          )}
        </div>
      </article>
    </section>
  );
};

export default FutureForecastChart;
